import {designShell,designHome,designCard,designCategoryCard,designCategories,designAnalytics,designTaxonomy,icon} from './ds6-design.js';
import {seeds as documentCategories} from './ds6-data.js';
import {splashScreen} from './ds6-splash.js';
import {welcomeScreen} from './ds6-welcome.js';
import {onboardingScreen} from './ds6-onboarding.js';
import {roleScreen} from './ds6-role.js';
import {loginScreen} from './ds6-login.js';
import {otpScreen} from './ds6-otp.js';
import {registerScreen} from './ds6-register.js';
import {registrationErrors} from './ds6-data.js';
import {completeProfileScreen} from './ds6-profile.js';
import {profileCompletionErrors} from './ds6-data.js';
import {interestsScreen} from './ds6-interests.js';
import {interestSelectionErrors} from './ds6-data.js';
import {userGroups,adminGroups,userScreens,adminScreens,experiences,rooms,themes,dresses,communities,money,initialState,bookingTotal,categoryErrors,listValues,bookingErrors,makeBooking,today} from './ds6-data.js';

const app=document.querySelector('#app');
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const storageKey='melo-ds6-state';
let state=initialState();
let storageFailure=false;
try{const saved=JSON.parse(localStorage.getItem(storageKey)||'null');if(saved?.version===6)state={...state,...saved,profile:{...state.profile,...saved.profile},draft:{...state.draft,...saved.draft}};}catch{storageFailure=true;}
const url=new URL(location.href);
const admin=location.pathname.startsWith('/admin');
if(!admin)state.role='user';
const numberFromPath=Number(location.pathname.match(/MEL-[UA]-(\d+)/)?.[1]);
const aliases={'/':11,'/customer':11,'/customer/experiences':12,'/customer/dream-room':35,'/customer/booking':22,'/customer/bookings':29,'/customer/profile':58,'/customer/about':2,'/customer/events':49,'/admin':6,'/admin/all-categories':11,'/admin/categories':11,'/admin/add-edit-category':12,'/admin/subcategories-tags':13};
let number=numberFromPath||aliases[location.pathname]||(admin?6:11);
if(!admin&&number===8){number=9;history.replaceState(null,'',location.pathname.replace('MEL-U-008','MEL-U-009')+location.search);}
const current=(admin?adminScreens:userScreens).find(s=>s.number===number);
document.body.dataset.portal=admin?'admin':'user';
document.body.dataset.screen=String(number);
const screenLink=(n,params={},isAdmin=admin)=>`${isAdmin?'/admin':'/customer'}/screens/MEL-${isAdmin?'A':'U'}-${String(n).padStart(3,'0')}${Object.keys(params).length?'?'+new URLSearchParams(params):''}`;
const go=(n,params={},isAdmin=admin)=>location.assign(screenLink(n,params,isAdmin));
const a=(n,label,params={},cls='',isAdmin=admin)=>`<a class="${cls}" href="${esc(screenLink(n,params,isAdmin))}" ${number===n&&admin===isAdmin?'aria-current="page"':''}>${label}</a>`;
const button=(n,label,params={},secondary=false)=>a(n,label,params,`button${secondary?' secondary':''}`);
const badge=text=>`<span class="badge">${esc(text)}</span>`;
const input=(label,name,value='',type='text',extra='')=>`<label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}>`;
const area=(label,name,value='',extra='')=>`<label for="${name}">${label}</label><textarea id="${name}" name="${name}" rows="3" ${extra}>${esc(value)}</textarea>`;
const select=(label,name,options,value)=>`<label for="${name}">${label}</label><select id="${name}" name="${name}">${options.map(o=>{const [v,t]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`}).join('')}</select>`;
const check=(label,name,checked=false,value='on')=>`<label class="check"><input type="checkbox" name="${name}" value="${esc(value)}" ${checked?'checked':''}><span>${label}</span></label>`;
const form=(action,body,label='Save changes')=>`<form data-action="${action}"><div class="form-error" role="alert" tabindex="-1" hidden></div>${body}<div class="form-actions"><button type="submit">${label}</button></div></form>`;
const empty=(title,description,action='')=>`<div class="empty"><h2>${title}</h2><p class="muted">${description}</p>${action}</div>`;
const pageHead=(title,subtitle='',action='')=>`<div class="page-heading"><div><div class="eyebrow">${admin?'Meetura admin / Melo Space':'Meetura / Melo Space · 18+'}</div><h1>${title}</h1>${subtitle?`<p class="muted">${subtitle}</p>`:''}</div>${action}</div>`;
const note=text=>`<div class="context-note">${text}</div>`;
function persist(){try{localStorage.setItem(storageKey,JSON.stringify(state));return true;}catch{toast('Unable to save: browser storage is unavailable.');return false;}}
// Upgrade only unchanged starter category names; preserve user-created and edited records.
if(!state.categoryDesignVersion){const oldNames={art:'Art & Craft',stage:'Performance & Open Mic',relax:'Reading & Relaxation',social:'Community & Meetups',private:'Private Rooms'};for(const seed of documentCategories){const existing=state.categories.find(c=>c.id===seed.id);if(!existing)state.categories.push(structuredClone(seed));else if(existing.name===oldNames[seed.id])Object.assign(existing,{name:seed.name,description:seed.description});}state.categoryDesignVersion=1;persist();}
function toast(text){const el=document.querySelector('#notice');el.textContent=text;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.textContent='',6000);}
function error(formEl,errors){const box=formEl.querySelector('.form-error');box.hidden=false;box.textContent=errors.join(' ');box.focus();}
function draftExperience(){return experiences.find(e=>e.id===state.draft.experience)||experiences[0];}
function exp(){return experiences.find(e=>e.id===url.searchParams.get('experience'))||draftExperience();}
function available(){return experiences.filter(e=>state.categories.find(c=>c.id===e.category)?.active).sort((a,b)=>Number(state.profile.interests.includes(b.category))-Number(state.profile.interests.includes(a.category)));}
function category(){return state.categories.find(c=>c.id===url.searchParams.get('category'))||state.categories[0];}
function booking(){return state.bookings.find(b=>b.id===url.searchParams.get('booking'))||state.bookings.at(-1);}
function bookingParams(){return booking()?{booking:booking().id}:{};}
function community(){return communities.find(c=>c.id===url.searchParams.get('community'))||communities[0];}
function row(label,value){return `<div class="detail-row"><span class="muted">${label}</span><strong>${esc(value)}</strong></div>`;}
function card(e){return designCard(e,{state,a,money});}
function categoryCard(c){return designCategoryCard(c,{a});}
function directory(groups,isAdmin){return groups.map(([group,start,names])=>`<details ${current?.group===group?'open':''}><summary>${esc(group)}</summary>${names.map((name,i)=>!isAdmin&&start+i===8?'':a(start+i,`<span class="screen-code">${String(start+i).padStart(3,'0')}</span>${esc(name)}`,{},'',isAdmin)).join('')}</details>`).join('');}
function shell(content){if(!admin&&number===1)return splashScreen(screenLink(2));if(!admin&&number===2)return welcomeScreen(screenLink);if(!admin&&number===3)return onboardingScreen(screenLink);if(!admin&&number===4)return roleScreen(screenLink,state.role);if(!admin&&number===5)return loginScreen(screenLink,state.role,Boolean(state.preferences.rememberDemoLogin));if(!admin&&number===6)return otpScreen(screenLink);if(!admin&&number===7)return registerScreen(screenLink,state.role);if(!admin&&number===9)return completeProfileScreen(screenLink,state.profile,state.categories);if(!admin&&number===10)return interestsScreen(screenLink,state.profile.interests,state.categories);if(admin&&number===12)content=`<div class="category-editor-layout"><div class="category-editor-context" inert aria-hidden="true">${designCategories({state,button,a,money,url})}</div><section class="category-editor-panel" aria-label="Category editor"><a class="category-editor-close" href="${screenLink(11)}" aria-label="Close category editor">×</a>${content}</section></div>`;return designShell({content,admin,current,number,state,a,screenLink,directory,userGroups,adminGroups});}
function loginView(isAdmin=false){return `<div class="auth-layout"><div><span class="eyebrow">One Meetura account</span><h2>${isAdmin?'Your category workspace.':'A little more you.'}</h2><p>Melo Space lives within Meetura. Your profile and account belong to the shared Meetura experience.</p><div class="art" aria-hidden="true"><span>✿</span></div></div><div class="card"><h2>${isAdmin?'Continue as demo admin':'Continue with Meetura'}</h2>${note('Live Meetura sign-in is not connected. This local preview uses an explicitly simulated session; no password or real OTP is collected.')}${form('demo-login',input('Demo display name','name',state.profile.name,'text','required maxlength="80"')+select('Demo role','role',isAdmin?[['admin','Admin']]:[['user','User']],isAdmin?'admin':state.role),isAdmin?'Open demo MFA step':'Open demo verification step')}${!isAdmin?`<div class="row">${a(7,'Create a demo account')}</div>`:a(3,'Account recovery')}</div></div>`;}
function verifyView(isAdmin=false){return `<div class="card narrow"><h2>${isAdmin?'Demo MFA verification':'Demo OTP verification'}</h2><p>This preview does not send verification messages. Enter the displayed test code <strong>123456</strong> to continue the local flow.</p>${form('verify',input('Test code','code','','text','required inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="off"'),'Verify demo code')}</div>`;}
function profileForm(action='profile'){return form(action,input('Display name','name',state.profile.name,'text','required maxlength="80"')+area('About you (optional)','bio',state.profile.bio,'maxlength="400"')+note('Use sample information in this browser-only preview.'));}
function profileView(){
  const upcoming=state.bookings.filter(b=>b.status!=='Cancelled'&&b.date>=today()).sort((a,b)=>(a.date+a.slot).localeCompare(b.date+b.slot));
  const next=upcoming[0];const interests=state.categories.filter(c=>(state.profile.interests||[]).includes(c.id));
  const shortcuts=[[29,'ticket','My bookings','Your plans, tickets and favourite moments',state.bookings.length+' bookings'],[20,'heart','Wishlist','Keep a little inspiration for another day',state.wishlist.length+' saved'],[50,'user','My communities','Find people who love what you love',state.communities.length+' joined'],[57,'bell','Notifications','Stay close to your latest updates','View updates'],[62,'chart','Payments & receipts','Keep your booking details together','View billing'],[63,'sparkles','Help & support','A little help whenever you need it','Get in touch']];
  return '<div class="member-space"><section class="member-hero"><div class="member-cover"><span>YOUR LITTLE WORLD OF EXPERIENCES</span>'+icon('sparkles')+'</div><div class="member-identity"><div class="member-photo">'+(state.profile.photo?'<img src="'+esc(state.profile.photo)+'" alt="Your profile photo">':icon('user'))+'</div><div class="member-intro"><span class="eyebrow">MY MELO SPACE</span><h2>'+esc(state.profile.name||'Hello, explorer')+'</h2><p>'+esc(state.profile.bio||'Make time for what makes you happy.')+'</p>'+(state.profile.city?'<span class="member-location">'+icon('room')+esc([state.profile.city,state.profile.country].filter(Boolean).join(', '))+'</span>':'')+'</div><div class="member-actions">'+button(9,'Edit profile')+button(61,icon('lock')+' Account security',{},true)+'</div></div><div class="member-stats">'+[[upcoming.length,'Upcoming experiences'],[state.wishlist.length,'Saved favourites'],[state.communities.length,'Communities joined']].map(([v,t])=>'<div><strong>'+v+'</strong><span>'+t+'</span></div>').join('')+'</div></section><div class="member-columns"><section class="member-next"><div class="member-section-title"><div><span class="eyebrow">SOMETHING TO LOOK FORWARD TO</span><h3>Your next experience</h3></div>'+a(29,'All bookings',{},'text-link')+'</div>'+(next?'<div class="member-reservation">'+icon('calendar')+'<div><h4>'+esc(next.title)+'</h4><p>'+esc(next.date)+' ? '+esc(next.slot)+'</p><span>'+esc(next.status)+'</span></div>'+button(30,'View booking',{booking:next.id})+'</div>':'<div class="member-empty"><img src="/assets/melo/workshop-hd.png" alt="A colourful creative workshop" loading="lazy"><div><h4>Your next happy moment starts here</h4><p>Try something creative, meet your people, or make a private room your own.</p>'+button(12,'Find an experience')+'</div></div>')+'</section><aside class="member-interests"><span class="eyebrow">A LITTLE MORE YOU</span><h3>Your interests</h3><p>Make space for the things you love.</p><div class="member-interest-tags">'+(interests.length?interests.map(c=>'<span>'+icon('heart')+esc(c.name)+'</span>').join(''):'<span>Discover what inspires you</span>')+'</div>'+a(10,'Update interests ?',{},'text-link')+'</aside></div><div class="member-section-title"><div><span class="eyebrow">EVERYTHING IN ONE PLACE</span><h3>Your account, at a glance</h3></div></div><nav class="member-shortcuts" aria-label="Your account">'+shortcuts.map(([n,i,t,d,count])=>a(n,'<span class="member-shortcut-icon">'+icon(i)+'</span><span class="member-shortcut-copy"><strong>'+t+'</strong><span>'+d+'</span><small>'+count+'</small></span><span class="member-shortcut-arrow" aria-hidden="true">?</span>',{},'member-shortcut')).join('')+'</nav></div>';
}
function discovery(){const c=url.searchParams.get('category');const q=url.searchParams.get('q')||'';const list=available().filter(e=>(!c||e.category===c)&&(!q||e.title.toLowerCase().includes(q.toLowerCase())||state.categories.find(x=>x.id===e.category)?.name.toLowerCase().includes(q.toLowerCase())));return `<form class="search-form" data-action="search"><label class="sr-only" for="q">Search experiences</label><input id="q" name="q" type="search" value="${esc(q)}" placeholder="Find your next little adventure"><button>Search</button></form><div class="filters">${a(12,'All experiences',{},'filter-link')} ${state.categories.filter(c=>c.active).map(c=>a(12,esc(c.name),{category:c.id},`filter-link ${url.searchParams.get('category')===c.id?'selected':''}`)).join('')}</div><div class="grid">${list.map(card).join('')}</div>${!list.length?empty('No experiences found','Try another category or search.',button(12,'Clear filters')):''}`;}
function home(){return designHome({state,available,button,a,card});}
function detailView(){const e=exp();if(!state.recent.includes(e.id)){state.recent=[...state.recent,e.id].slice(-12);persist();}const cat=state.categories.find(c=>c.id===e.category);return `<section class="hero"><div><span class="eyebrow">${esc(cat?.name||'Experience')} · Ages 18+</span><h2 class="display-title">${esc(e.title)}</h2><p>${esc(cat?.description||'A creative experience within Meetura.')}</p><p>${e.duration} · Demo venue · Materials included</p><strong>${money(e.price)} / ${e.id==='dream'?'room':'person'}</strong><div class="form-actions">${button(e.id==='dream'?38:22,'Choose your session',{experience:e.id})}${button(17,'View gallery',{experience:e.id},true)}</div></div><div class="detail-art"><img src="/assets/melo/${({art:'crochet',pottery:'craft',music:'meetup',reading:'wellness',meetup:'meetup',dream:'room'})[e.id]}.png" alt="${esc(e.title)}"></div></section><nav class="experience-section-nav" aria-label="Experience information"><a href="#experience-team">The Melo team</a><a href="#experience-venue">Venue</a><a href="#experience-guidance">Before you book</a><a href="#experience-reviews">Reviews</a></nav><div class="experience-information"><details open id="experience-team" class="experience-info-section"><summary class="experience-info-title">${icon('user')}<div><span class="eyebrow">A WARM WELCOME</span><h3>Your Melo team</h3></div><span class="experience-disclosure-arrow" aria-hidden="true">?</span></summary><div class="experience-team-copy"><span class="experience-team-avatar">${icon('sparkles')}</span><div><h4>${esc(e.host)}</h4><p>Your experience is organised by the Melo Space team. Facilitator biographies and session assignments will appear here when supplied.</p></div></div></details><details open id="experience-venue" class="experience-info-section"><summary class="experience-info-title">${icon('room')}<div><span class="eyebrow">WHERE WE MEET</span><h3>The space for your experience</h3></div><span class="experience-disclosure-arrow" aria-hidden="true">?</span></summary><p>No live venue address or map has been configured for this preview.</p><dl class="experience-venue-facts"><div><dt>Session timezone</dt><dd>Asia/Kolkata</dd></div><div><dt>Address & directions</dt><dd>Awaiting venue information</dd></div><div><dt>Accessibility & amenities</dt><dd>Details to be confirmed</dd></div></dl></details><details open id="experience-guidance" class="experience-info-section"><summary class="experience-info-title">${icon('ticket')}<div><span class="eyebrow">PLAN YOUR VISIT</span><h3>Before you book</h3></div><span class="experience-disclosure-arrow" aria-hidden="true">?</span></summary><ul class="experience-guidance-list"><li><strong>Age requirement</strong><span>All participants must be aged 18 or above.</span></li><li><strong>Session length</strong><span>${esc(e.duration)}</span></li><li><strong>Booking availability</strong><span>Prices and inventory in this preview are sample data. No live payment is collected.</span></li><li><strong>Venue & policies</strong><span>Final venue details, inclusions and cancellation rules will be shown here once configured.</span></li></ul></details><details open id="experience-reviews" class="experience-info-section"><summary class="experience-info-title">${icon('heart')}<div><span class="eyebrow">SHARED MOMENTS</span><h3>Reviews & ratings</h3></div><span class="experience-disclosure-arrow" aria-hidden="true">?</span></summary>${state.reviews.filter(r=>r.experience===e.id).map(r=>'<article class="message"><strong>'+esc(r.author)+' ? '+esc(r.rating)+'/5</strong><p>'+esc(r.text)+'</p></article>').join('')||'<p>No local reviews yet.</p>'}<div class="experience-review-form"><h4>Share a sample review</h4>${form('review','<input type="hidden" name="experience" value="'+esc(e.id)+'"><input type="hidden" name="inline" value="true">'+select('Rating','rating',[1,2,3,4,5],5)+area('Your sample review','text','','required maxlength="1000"'),'Save demo review')}</div></details></div>`;}
function dateForm(privateRoom=false){const d=state.draft;return form('date',select('Experience','experience',available().filter(e=>privateRoom?e.id==='dream':true).map(e=>[e.id,e.title]),d.experience)+input('Date · Asia/Kolkata','date',d.date,'date',`required min="${today()}"`)+select('Sample time slot','slot',[['10:00','10:00 AM'],['13:00','1:00 PM'],['16:00','4:00 PM']],d.slot)+note('Times shown are sample choices. Live availability is not connected.'),privateRoom?'Review private room':'View session details');}
function participantForm(){return form('participants',input('Number of participants','count',state.draft.count,'number',`required min="1" max="${state.draft.experience==='dream'?(rooms.find(r=>r.id===state.draft.room)?.capacity||4):8}"`)+area('Participant names (sample data only)','guests',state.draft.guests,'required maxlength="500"')+check('I confirm every participant is 18 or older.','adult',state.profile.adult),'Review booking');}
function draftSummary(privateRoom=false){const d=state.draft;const e=draftExperience();return `<div class="checkout-grid"><div class="card"><h2>${esc(e.title)}</h2>${row('Date',d.date||'Not selected')}${row('Slot (Asia/Kolkata)',d.slot)}${row('Participants',d.count)}${row('Names',d.guests||'Not entered')}${privateRoom?row('Room',rooms.find(r=>r.id===d.room)?.name||'Not selected')+row('Theme',d.theme)+row('Decoration items',d.decor.join(', ')||'None')+row('Outfit',dresses.find(x=>x.id===d.dress)?.name||'None')+row('Size',d.dress?d.size:'Not applicable')+row('Accessories',d.accessories.join(', ')||'None'):''}${row('Sample total',money(bookingTotal(d)))}<p class="small muted">No live taxes, offers, or payment processing configured.</p><div class="row">${button(privateRoom?44:22,'Edit date',{},true)}${button(24,'Edit participants',{},true)}${button(8,'Age eligibility',{},true)}</div></div><div class="card"><h3>Before you continue</h3><p>This prototype creates a demo reservation. It does not collect payment or guarantee inventory.</p>${privateRoom?button(27,'Continue to demo checkout'):button(26,'Offers & checkout')}${privateRoom?`<div class="form-actions">${button(40,'Edit room selections',{},true)}</div>`:''}</div></div>`;}
function bookingsTable(items=state.bookings){return items.length?`<div class="table-wrap" tabindex="0" role="region" aria-label="Booking records"><table><thead><tr><th>Booking</th><th>Experience</th><th>Date / time</th><th>Sample value</th><th>Status</th><th>Details</th></tr></thead><tbody>${items.slice().reverse().map(b=>`<tr><td>${esc(b.id)}</td><td>${esc(b.title)}<br><span class="muted">${esc(b.guests)}</span></td><td>${esc(b.date)}<br>${esc(b.slot)}</td><td>${money(b.total)}</td><td>${badge(b.status)}</td><td>${a(30,'Open',{booking:b.id},'text-link',false)}</td></tr>`).join('')}</tbody></table></div>`:empty('Your next experience is waiting','There are no demo reservations yet.',a(12,'Explore experiences',{},'button',false));}
function selectedBooking(view){const b=booking();if(!b)return empty('No booking selected','Create a demo booking to try this screen.',button(12,'Explore experiences'));const params={booking:b.id};if(view==='reschedule')return `<div class="card narrow">${note('Local rescheduling updates this demo record only. Real availability and eligibility must be verified by Meetura.')}${b.status==='Cancelled'?'<p>Cancelled bookings cannot be rescheduled.</p>':form('reschedule',`<input type="hidden" name="booking" value="${esc(b.id)}">`+input('New date','date',b.date,'date',`required min="${today()}"`)+select('New time','slot',['10:00','13:00','16:00'],b.slot),'Save demo reschedule')}</div>`;if(view==='cancel')return `<div class="card narrow"><h2>Cancel ${esc(b.title)}?</h2><p>This changes the local demo record to cancelled. No money was collected, so no refund will be issued.</p>${b.status==='Cancelled'?badge('Already cancelled')+'<div class="form-actions">'+button(30,'Keep viewing booking',params,true)+'</div>':`<form data-action="cancel" class="cancel-booking-form"><div class="form-error" role="alert" tabindex="-1" hidden></div><input type="hidden" name="booking" value="${esc(b.id)}">${check('I want to cancel this demo booking.','confirm')}<div class="form-actions cancel-booking-actions"><button type="submit">Cancel demo booking</button>${button(30,'Keep viewing booking',params,true)}</div></form>`}</div>`;if(view==='refund')return `<div class="card"><h2>Refund status</h2>${row('Booking',b.id)}${row('Booking status',b.status)}${row('Payment',b.payment)}${note('No payment was collected. There is no refund transaction for this demo reservation.')}</div>`;if(view==='pass')return `<div class="card narrow ticket-card"><span class="eyebrow">Demo entry reference</span><h2>${esc(b.title)}</h2><p>${esc(b.date)} · ${esc(b.slot)} · Asia/Kolkata</p><div class="ticket">${esc(b.id)}</div>${badge(b.status)}<p>No valid QR ticket is issued in this preview. A production entry pass must be generated and verified by the shared booking system.</p><button data-download="${esc(b.id)}">Download demo reference (.txt)</button></div>`;return `<div class="card"><div class="row spread"><h2>${esc(b.title)}</h2>${badge(b.status)}</div>${row('Reference',b.id)}${row('Date / time',`${b.date} · ${b.slot} · Asia/Kolkata`)}${row('Participants',b.count)}${row('Names',b.guests)}${row('Sample value',money(b.total))}${row('Payment',b.payment)}${b.experience==='dream'?row('Theme',b.theme):''}<div class="form-actions">${button(31,'Digital entry reference',params)}${button(32,'Reschedule',params,true)}${button(33,'Cancel booking',params,true)}${button(34,'Refund status',params,true)}</div></div>`;}
function roomCatalogue(){return `<div class="grid">${rooms.map(r=>`<article class="card"><div class="card-art" aria-hidden="true">☾</div><h2>${r.name}</h2><p>Up to ${r.capacity} adults · 2 hours</p><strong>${money(r.price)} / room</strong><p>${a(37,'View package',{room:r.id,experience:'dream'},'button secondary')}</p></article>`).join('')}</div>`;}
function communityCards(onlyMine=false){const list=communities.filter(c=>!onlyMine||state.communities.includes(c.id));return list.length?`<div class="grid">${list.map(c=>`<article class="card"><div class="category-mark" aria-hidden="true">◎</div><h2>${c.name}</h2><p>${c.description}</p>${a(48,'View community',{community:c.id},'button secondary')}</article>`).join('')}</div>`:empty('Find your people','Join a sample community to see it here.',button(47,'Explore communities'));}
function notifications(){const items=state.bookings.slice().reverse().map(b=>`${b.status}: ${b.title} · ${b.date}`).concat(state.tickets.map(t=>`Support request ${t.id}: ${t.subject}`));return `<div class="card">${items.length?items.map(t=>`<div class="notification-row">${esc(t)}</div>`).join(''):empty('All caught up','Booking and support updates will appear here as you try the local flows.')}</div>`;}
function settingsView(isAdmin=false){return `<div class="card narrow"><h2>Shared Meetura account</h2><p>Password, device sessions, recovery methods, and MFA are managed through the shared Meetura identity system.</p>${note('The identity service is not connected. This preview does not create real accounts or change passwords.')}${row('Preview session',isAdmin?(state.adminSession?'Demo admin active':'Not active'):(state.demoSession?'Demo user active':'Not active'))}${form('end-session','<p>End this simulated session on this browser.</p>','End demo session')}</div>`;}
